1. namespace TradeRecon.Domain;
2. 
3. /// <summary>
4. /// A single reconciliation break. Breaks are value objects: given identical inputs the
5. /// engine always produces the same set of breaks with the same <see cref="BreakKey"/>,
6. /// which is what makes reruns idempotent and manual overrides stable.
7. /// </summary>
8. public sealed record ReconciliationBreak
9. {
10.     public required DateOnly BusinessDate { get; init; }
11.     public required BreakType Type { get; init; }
12.     public required ReconciliationKey Key { get; init; }
13. 
14.     /// <summary>Internal trade identifier involved in the break, when applicable.</summary>
15.     public string? TradeId { get; init; }
16. 
17.     /// <summary>Settlement identifier involved in the break, when applicable.</summary>
18.     public string? SettlementId { get; init; }
19. 
20.     /// <summary>Human-readable description of the discrepancy (no sensitive PII).</summary>
21.     public required string Detail { get; init; }
22. 
23.     /// <summary>Magnitude of the discrepancy where meaningful (quantity, amount or days).</summary>
24.     public decimal? Difference { get; init; }
25. 
26.     public BreakStatus Status { get; init; } = BreakStatus.Open;
27. 
28.     /// <summary>
29.     /// Stable identity of the break, independent of mutable status. Two breaks describing
30.     /// the same discrepancy on the same business date share a break key.
31.     /// </summary>
32.     public string BreakKey => string.Join(
33.         '|',
34.         BusinessDate.ToString("yyyyMMdd"),
35.         Type,
36.         Key.ToString(),
37.         TradeId ?? "-",
38.         SettlementId ?? "-");
39. }
40.

