1. using System.Globalization;
2. using Microsoft.Extensions.DependencyInjection;
3. using Microsoft.Extensions.Logging;
4. using Microsoft.Extensions.Logging.Console;
5. using TradeRecon.Application.Reconciliation;
6. using TradeRecon.Application.Reporting;
7. using TradeRecon.Domain;
8. using TradeRecon.Infrastructure;
9. 
10. namespace TradeRecon.Console;
11. 
12. /// <summary>
13. /// Console host for the canonical trade-reconciliation baseline. Runs a deterministic
14. /// end-of-day reconciliation over the synthetic CSV fixtures and writes the reports.
15. ///
16. /// This host exposes a stable, black-box-friendly CLI contract:
17. ///   * Inputs come from a fixture directory (--fixtures) containing trades.csv,
18. ///     settlements.csv and positions.csv.
19. ///   * Reports are written under --out/&lt;yyyy-MM-dd&gt;/ as eod-summary.txt,
20. ///     eod-break-register.csv and eod-result.json.
21. ///   * With --json the deterministic JSON result is written to stdout (and all logs are
22. ///     routed to stderr) so stdout contains nothing but the JSON document.
23. ///   * Exit codes: 0 = clean, 2 = breaks outstanding, 1 = input/processing error.
24. ///
25. /// Usage: TradeRecon.Console [--date yyyy-MM-dd] [--fixtures &lt;dir&gt;] [--out &lt;dir&gt;] [--json]
26. /// </summary>
27. public static class Program
28. {
29.     /// <summary>Reconciliation completed with no open breaks.</summary>
30.     public const int ExitClean = 0;
31. 
32.     /// <summary>Input or processing error (e.g. missing or malformed fixtures).</summary>
33.     public const int ExitError = 1;
34. 
35.     /// <summary>Reconciliation completed but open breaks remain.</summary>
36.     public const int ExitBreaks = 2;
37. 
38.     public static async Task<int> Main(string[] args)
39.     {
40.         if (args.Contains("--help") || args.Contains("-h"))
41.         {
42.             System.Console.WriteLine(
43.                 "Usage: TradeRecon.Console [--date yyyy-MM-dd] [--fixtures <dir>] [--out <dir>] [--json]");
44.             return ExitClean;
45.         }
46. 
47.         CliOptions options;
48.         try
49.         {
50.             options = CliOptions.Parse(args);
51.         }
52.         catch (Exception ex) when (ex is FormatException or ArgumentException or PathTooLongException or NotSupportedException)
53.         {
54.             System.Console.Error.WriteLine($"Invalid arguments: {ex.Message}");
55.             return ExitError;
56.         }
57. 
58.         using var loggerFactory = LoggerFactory.Create(builder =>
59.         {
60.             builder.SetMinimumLevel(LogLevel.Information);
61.             builder.AddSimpleConsole(o =>
62.             {
63.                 o.SingleLine = true;
64.                 o.TimestampFormat = "HH:mm:ss ";
65.             });
66.             // In JSON mode keep stdout pure by sending every log line to stderr.
67.             if (options.JsonOutput)
68.             {
69.                 builder.Services.Configure<ConsoleLoggerOptions>(
70.                     o => o.LogToStandardErrorThreshold = LogLevel.Trace);
71.             }
72.         });
73. 
74.         var services = new ServiceCollection();
75.         services.AddSingleton<ILoggerFactory>(loggerFactory);
76.         services.AddLogging();
77.         services.AddTradeReconCore();
78.         services.AddTradeReconInfrastructure(options.FixturesDirectory, options.OutputDirectory);
79. 
80.         await using var provider = services.BuildServiceProvider();
81.         var logger = provider.GetRequiredService<ILogger<object>>();
82.         var runner = provider.GetRequiredService<ReconciliationRunner>();
83.         var reportBuilder = provider.GetRequiredService<EndOfDayReportBuilder>();
84. 
85.         var runOptions = new ReconciliationRunOptions
86.         {
87.             Tolerances = new ToleranceOptions
88.             {
89.                 QuantityAbsolute = 0m,
90.                 AmountAbsolute = 0.01m,
91.                 SettlementDateDays = 0,
92.                 PositionQuantityAbsolute = 0m
93.             }
94.         };
95. 
96.         try
97.         {
98.             var result = await runner.RunAsync(options.BusinessDate, runOptions).ConfigureAwait(false);
99. 
100.             if (options.JsonOutput)
101.             {
102.                 System.Console.Out.Write(reportBuilder.BuildJson(result));
103.                 System.Console.Out.Write('\n');
104.             }
105.             else
106.             {
107.                 System.Console.WriteLine();
108.                 System.Console.WriteLine($"Business date : {result.BusinessDate:yyyy-MM-dd}");
109.                 System.Console.WriteLine($"Matched pairs : {result.Matches.Count}");
110.                 System.Console.WriteLine($"Open breaks   : {result.OpenBreaks.Count}");
111.                 System.Console.WriteLine($"Overridden    : {result.OverriddenBreaks.Count}");
112.                 System.Console.WriteLine($"Status        : {EndOfDayReportBuilder.StatusText(result)}");
113.                 System.Console.WriteLine($"Reports       : {options.OutputDirectory}");
114.             }
115. 
116.             return result.IsClean ? ExitClean : ExitBreaks;
117.         }
118.         catch (Exception ex) when (ex is FileNotFoundException or DirectoryNotFoundException or FormatException)
119.         {
120.             logger.LogError(ex, "Reconciliation failed: {Message}", ex.Message);
121.             return ExitError;
122.         }
123.     }
124. 
125.     private sealed record CliOptions(
126.         DateOnly BusinessDate,
127.         string FixturesDirectory,
128.         string OutputDirectory,
129.         bool JsonOutput)
130.     {
131.         public static CliOptions Parse(string[] args)
132.         {
133.             var date = new DateOnly(2024, 6, 3);
134.             var baseDir = AppContext.BaseDirectory;
135.             var fixtures = Path.GetFullPath(Path.Combine(baseDir, "fixtures"));
136.             var output = Path.GetFullPath(Path.Combine(baseDir, "reports"));
137.             var json = false;
138. 
139.             for (var i = 0; i < args.Length; i++)
140.             {
141.                 switch (args[i])
142.                 {
143.                     case "--date":
144.                         date = DateOnly.ParseExact(NextValue(args, ref i, "--date"), "yyyy-MM-dd", CultureInfo.InvariantCulture);
145.                         break;
146.                     case "--fixtures":
147.                         fixtures = Path.GetFullPath(NextValue(args, ref i, "--fixtures"));
148.                         break;
149.                     case "--out":
150.                         output = Path.GetFullPath(NextValue(args, ref i, "--out"));
151.                         break;
152.                     case "--json":
153.                         json = true;
154.                         break;
155.                     default:
156.                         throw new ArgumentException($"Unknown argument '{args[i]}'.");
157.                 }
158.             }
159. 
160.             return new CliOptions(date, fixtures, output, json);
161.         }
162. 
163.         private static string NextValue(string[] args, ref int index, string option)
164.         {
165.             if (index + 1 >= args.Length || args[index + 1].StartsWith("--", StringComparison.Ordinal))
166.             {
167.                 throw new ArgumentException($"Option {option} requires a value.");
168.             }
169. 
170.             return args[++index];
171.         }
172.     }
173. }
