525.     private static AuditEntry CreateAuditEntry(AuditState state, string requestId, string action, string actor, string role, string businessDate)
526.     {
527.         var previousHash = state.Entries.Count > 0 ? state.Entries[^1].Hash : "genesis";
528.         var timestamp = DateTimeOffset.UtcNow.ToString("O");
529.         var sequence = state.Sequence + 1;
530.         var entry = new AuditEntry
531.         {
532.             RequestId = requestId,
533.             Action = action,
534.             Actor = actor,
535.             Role = role,
536.             BusinessDate = businessDate,
537.             Timestamp = timestamp,
538.             Sequence = sequence,
539.             Version = state.Version,
540.             PreviousHash = previousHash,
541.             Decision = null,
542.             IsFinalDecision = false
543.         };
544. 
545.         var payload = JsonSerializer.Serialize(new
546.         {
547.             requestId = entry.RequestId,
548.             action = entry.Action,
549.             actor = entry.Actor,
550.             role = entry.Role,
551.             businessDate = entry.BusinessDate,
552.             timestamp = entry.Timestamp,
553.             sequence = entry.Sequence,
554.             version = entry.Version,
555.             previousHash = entry.PreviousHash,
556.             decision = entry.Decision,
557.             isFinalDecision = entry.IsFinalDecision,
558.             reason = entry.Reason,
559.             evidence = entry.Evidence
560.         }, AuditJsonOptions);
561. 
562.         entry.Hash = ComputeHash(previousHash + "|" + payload);
