616.     private static string SanitizeOutput(string? value)
617.     {
618.         if (string.IsNullOrWhiteSpace(value))
619.         {
620.             return string.Empty;
621.         }
622. 
623.         var sanitized = value;
624.         sanitized = Regex.Replace(sanitized, @"(?i)\b(?:account|acct|customer|trade|settlement)[\s:=/-]*[A-Z0-9-]{2,}\b", "[ACCOUNT_REDACTED]");
625.         sanitized = Regex.Replace(sanitized, @"(?i)\bACC[A-Z0-9-]+\b", "[ACCOUNT_REDACTED]");
626.         sanitized = Regex.Replace(sanitized, @"(?i)\b[A-Z]{2,}[0-9]{3,}\b", "[ACCOUNT_REDACTED]");
627.         sanitized = Regex.Replace(sanitized, @"(?i)(?:USD|EUR|GBP|JPY|CAD|AUD|CHF|CNY|RUB|INR|NOK|SEK|MXN|NZD)\s*[-$]?\d[\d,]*(?:\.\d+)?", "[AMOUNT_REDACTED]");
628.         sanitized = Regex.Replace(sanitized, @"(?i)\$\d[\d,]*(?:\.\d+)?", "[AMOUNT_REDACTED]");
629.         sanitized = Regex.Replace(sanitized, @"(?i)\b\d[\d,]*(?:\.\d+)?\b(?=\s*(?:amount|value|notional|principal|total|settlement|trade))", "[AMOUNT_REDACTED]");
630.         return sanitized;
631.     }
