     private static AuditEntry CreateAuditEntry(AuditState state, string requestId, string action, string actor, string role, string businessDate)
     {
         var previousHash = state.Entries.Count > 0 ? state.Entries[^1].Hash : "genesis";
         var timestamp = DateTimeOffset.UtcNow.ToString("O");
         var sequence = state.Sequence + 1;
         var entry = new AuditEntry
         {
             RequestId = requestId,
             Action = action,
             Actor = actor,
             Role = role,
             BusinessDate = businessDate,
             Timestamp = timestamp,
             Sequence = sequence,
             Version = state.Version,
             PreviousHash = previousHash,
             Decision = null,
             IsFinalDecision = false
         };

         var payload = JsonSerializer.Serialize(new
         {
             requestId = entry.RequestId,
             action = entry.Action,
             actor = entry.Actor,
             role = entry.Role,
             businessDate = entry.BusinessDate,
             timestamp = entry.Timestamp,
             sequence = entry.Sequence,
             version = entry.Version,
             previousHash = entry.PreviousHash,
             decision = entry.Decision,
             isFinalDecision = entry.IsFinalDecision,
             reason = entry.Reason,
             evidence = entry.Evidence
         }, AuditJsonOptions);

         entry.Hash = ComputeHash(previousHash + "|" + payload);
         state.Sequence = sequence;
         return entry;
     }

     private static string ComputeHash(string value)
     {
         var bytes = SHA256.HashData(Encoding.UTF8.GetBytes(value));
         return Convert.ToHexString(bytes).ToLowerInvariant();
     }

     private static object MapEntryForExport(AuditEntry entry)
     {
         return new
         {
             requestId = SanitizeOutput(entry.RequestId),
             action = SanitizeOutput(entry.Action),
             actor = SanitizeOutput(entry.Actor),
             role = SanitizeOutput(entry.Role),
             businessDate = SanitizeOutput(entry.BusinessDate),
             timestamp = SanitizeOutput(entry.Timestamp),
             sequence = entry.Sequence,
             version = entry.Version,
             hash = SanitizeOutput(entry.Hash),
             previousHash = SanitizeOutput(entry.PreviousHash),
             decision = SanitizeOutput(entry.Decision),
             isFinalDecision = entry.IsFinalDecision,
             reason = SanitizeOutput(entry.Reason),
             evidence = SanitizeOutput(entry.Evidence)
         };
     }

     private static string GetRequiredValue(string[] args, params string[] optionNames)
     {
         foreach (var optionName in optionNames)
         {
             var index = Array.FindIndex(args, arg => string.Equals(arg, optionName, StringComparison.OrdinalIgnoreCase));
             if (index >= 0)
             {
                 if (index + 1 >= args.Length || args[index + 1].StartsWith("--", StringComparison.Ordinal))
                 {
                     throw new ArgumentException($"Option {optionName} requires a value.");
                 }

                 return args[index + 1];
             }
         }

         throw new ArgumentException($"Missing required option ({string.Join(", ", optionNames)}).");
     }

     private static void WriteAuditJson(object payload)
         => System.Console.WriteLine(JsonSerializer.Serialize(payload, AuditJsonOptions));

     private static string SanitizeOutput(string? value)
     {
         if (string.IsNullOrWhiteSpace(value))
         {
             return string.Empty;
         }

         var sanitized = value;
         sanitized = Regex.Replace(sanitized, @"(?i)\b(?:account|acct|customer|trade|settlement)[\s:=/-]*[A-Z0-9-]{2,}\b", "[ACCOUNT_REDACTED]");
         sanitized = Regex.Replace(sanitized, @"(?i)\bACC[A-Z0-9-]+\b", "[ACCOUNT_REDACTED]");
         sanitized = Regex.Replace(sanitized, @"(?i)\b[A-Z]{2,}[0-9]{3,}\b", "[ACCOUNT_REDACTED]");
         sanitized = Regex.Replace(sanitized, @"(?i)(?:USD|EUR|GBP|JPY|CAD|AUD|CHF|CNY|RUB|INR|NOK|SEK|MXN|NZD)\s*[-$]?\d[\d,]*(?:\.\d+)?", "[AMOUNT_REDACTED]");
         sanitized = Regex.Replace(sanitized, @"(?i)\$\d[\d,]*(?:\.\d+)?", "[AMOUNT_REDACTED]");
         sanitized = Regex.Replace(sanitized, @"(?i)\b\d[\d,]*(?:\.\d+)?\b(?=\s*(?:amount|value|notional|principal|total|settlement|trade))", "[AMOUNT_REDACTED]");
         return sanitized;
     }

     private sealed class AuditStateLock : IDisposable
     {
         private readonly FileStream _stream;

         public AuditStateLock(string stateDirectory)
         {
             Directory.CreateDirectory(stateDirectory);
             _stream = new FileStream(Path.Combine(stateDirectory, "audit.lock"), FileMode.OpenOrCreate, FileAccess.ReadWrite, FileShare.None);
         }

         public Task AcquireAsync()
         {
             _stream.Lock(0, 0);
             return Task.CompletedTask;
         }

         public void Dispose()
         {
             _stream.Unlock(0, 0);
             _stream.Dispose();
         }
     }

     private sealed class AuditState
     {
         public int Version { get; set; } = 1;
         public long Sequence { get; set; }
         public List<AuditEntry> Entries { get; set; } = new();
         public Dictionary<string, AuditRequestRecord> Requests { get; set; } = new(StringComparer.OrdinalIgnoreCase);
     }

     private sealed class AuditEntry
     {
         public string RequestId { get; set; } = string.Empty;
         public string Action { get; set; } = string.Empty;
         public string Actor { get; set; } = string.Empty;
         public string Role { get; set; } = string.Empty;
         public string BusinessDate { get; set; } = string.Empty;
         public string Timestamp { get; set; } = string.Empty;
         public long Sequence { get; set; }
         public int Version { get; set; } = 1;
         public string Hash { get; set; } = string.Empty;
         public string PreviousHash { get; set; } = string.Empty;
         public string? Decision { get; set; }
         public bool IsFinalDecision { get; set; }
         public string Reason { get; set; } = string.Empty;
         public string Evidence { get; set; } = string.Empty;
     }

     private sealed class AuditRequestRecord
     {
         public string RequestId { get; set; } = string.Empty;
         public string Proposer { get; set; } = string.Empty;
         public string BusinessDate { get; set; } = string.Empty;
         public string Reason { get; set; } = string.Empty;
         public string Evidence { get; set; } = string.Empty;
         public string ProposalHash { get; set; } = string.Empty;
         public long ProposalSequence { get; set; }
         public string? FinalDecision { get; set; }
         public string? FinalChecker { get; set; }
         public DateTimeOffset? DecidedAt { get; set; }
     }

     private sealed record CliOptions(
         DateOnly BusinessDate,
         string FixturesDirectory,
         string OutputDirectory,
         bool JsonOutput)
     {
         public static CliOptions Parse(string[] args)
         {
             var date = new DateOnly(2024, 6, 3);
             var baseDir = AppContext.BaseDirectory;
             var fixtures = Path.GetFullPath(Path.Combine(baseDir, "fixtures"));
             var output = Path.GetFullPath(Path.Combine(baseDir, "reports"));
             var json = false;

             for (var i = 0; i < args.Length; i++)
             {
                 switch (args[i])
                 {
                     case "--date":
                         date = DateOnly.ParseExact(NextValue(args, ref i, "--date"), "yyyy-MM-dd", CultureInfo.InvariantCulture);
                         break;
                     case "--fixtures":
                         fixtures = Path.GetFullPath(NextValue(args, ref i, "--fixtures"));
                         break;
                     case "--out":
                         output = Path.GetFullPath(NextValue(args, ref i, "--out"));
                         break;
                     case "--json":
                         json = true;
                         break;
                     default:
                         throw new ArgumentException($"Unknown argument '{args[i]}'.");
                 }
             }

             return new CliOptions(date, fixtures, output, json);
         }

         private static string NextValue(string[] args, ref int index, string option)
         {
             if (index + 1 >= args.Length || args[index + 1].StartsWith("--", StringComparison.Ordinal))
             {
                 throw new ArgumentException($"Option {option} requires a value.");
             }

             return args[++index];
         }
     }
 }

