1. using System.Globalization;
2. using System.Security.Cryptography;
3. using System.Text;
4. using System.Text.Json;
5. using System.Text.Json.Serialization;
6. using System.Text.RegularExpressions;
7. using Microsoft.Extensions.DependencyInjection;
8. using Microsoft.Extensions.Logging;
9. using Microsoft.Extensions.Logging.Console;
10. using TradeRecon.Application.Reconciliation;
11. using TradeRecon.Application.Reporting;
12. using TradeRecon.Domain;
13. using TradeRecon.Infrastructure;
14. 
15. namespace TradeRecon.Console;
16. 
17. /// <summary>
18. /// Console host for the canonical trade-reconciliation baseline. Runs a deterministic
19. /// end-of-day reconciliation over the synthetic CSV fixtures and writes the reports.
20. ///
21. /// This host exposes a stable, black-box-friendly CLI contract:
22. ///   * Inputs come from a fixture directory (--fixtures) containing trades.csv,
23. ///     settlements.csv and positions.csv.
24. ///   * Reports are written under --out/&lt;yyyy-MM-dd&gt;/ as eod-summary.txt,
25. ///     eod-break-register.csv and eod-result.json.
26. ///   * With --json the deterministic JSON result is written to stdout (and all logs are
27. ///     routed to stderr) so stdout contains nothing but the JSON document.
28. ///   * Exit codes: 0 = clean, 2 = breaks outstanding, 1 = input/processing error.
29. ///
30. /// Usage: TradeRecon.Console [--date yyyy-MM-dd] [--fixtures &lt;dir&gt;] [--out &lt;dir&gt;] [--json]
31. /// </summary>
32. public static class Program
33. {
34.     private const string AuditCommandInitialize = "initialize";
35.     private const string AuditCommandPropose = "propose";
36.     private const string AuditCommandDecide = "decide";
37.     private const string AuditCommandExport = "export";
38.     private const string AuditCommandHelp = "help";
39. 
40.     private static readonly JsonSerializerOptions AuditJsonOptions = new()
41.     {
42.         PropertyNamingPolicy = JsonNamingPolicy.CamelCase,
43.         DefaultIgnoreCondition = JsonIgnoreCondition.Never,
44.         WriteIndented = false
45.     };
46. 
47.     /// <summary>Reconciliation completed with no open breaks.</summary>
48.     public const int ExitClean = 0;
49. 
50.     /// <summary>Input or processing error (e.g. missing or malformed fixtures).</summary>
51.     public const int ExitError = 1;
52. 
53.     /// <summary>Reconciliation completed but open breaks remain.</summary>
54.     public const int ExitBreaks = 2;
55. 
56.     public static async Task<int> Main(string[] args)
57.     {
58.         if (args.Length > 0 && IsAuditCommand(args[0]))
59.         {
60.             return await HandleAuditCommandAsync(args).ConfigureAwait(false);
61.         }
62. 
63.         if (args.Contains("--help") || args.Contains("-h"))
64.         {
65.             System.Console.WriteLine(
66.                 "Usage: TradeRecon.Console [--date yyyy-MM-dd] [--fixtures <dir>] [--out <dir>] [--json]");
67.             return ExitClean;
68.         }
69. 
70.         CliOptions options;
71.         try
72.         {
73.             options = CliOptions.Parse(args);
74.         }
75.         catch (Exception ex) when (ex is FormatException or ArgumentException or PathTooLongException or NotSupportedException)
76.         {
77.             System.Console.Error.WriteLine($"Invalid arguments: {ex.Message}");
78.             return ExitError;
79.         }
80. 
81.         using var loggerFactory = LoggerFactory.Create(builder =>
82.         {
83.             builder.SetMinimumLevel(LogLevel.Information);
84.             builder.AddSimpleConsole(o =>
85.             {
86.                 o.SingleLine = true;
87.                 o.TimestampFormat = "HH:mm:ss ";
88.             });
89.             // In JSON mode keep stdout pure by sending every log line to stderr.
90.             if (options.JsonOutput)
91.             {
92.                 builder.Services.Configure<ConsoleLoggerOptions>(
93.                     o => o.LogToStandardErrorThreshold = LogLevel.Trace);
94.             }
95.         });
96. 
97.         var services = new ServiceCollection();
98.         services.AddSingleton<ILoggerFactory>(loggerFactory);
99.         services.AddLogging();
100.         services.AddTradeReconCore();
101.         services.AddTradeReconInfrastructure(options.FixturesDirectory, options.OutputDirectory);
102. 
103.         await using var provider = services.BuildServiceProvider();
104.         var logger = provider.GetRequiredService<ILogger<object>>();
105.         var runner = provider.GetRequiredService<ReconciliationRunner>();
106.         var reportBuilder = provider.GetRequiredService<EndOfDayReportBuilder>();
107. 
108.         var runOptions = new ReconciliationRunOptions
109.         {
110.             Tolerances = new ToleranceOptions
111.             {
112.                 QuantityAbsolute = 0m,
113.                 AmountAbsolute = 0.01m,
114.                 SettlementDateDays = 0,
115.                 PositionQuantityAbsolute = 0m
116.             }
117.         };
118. 
119.         try
120.         {
121.             var result = await runner.RunAsync(options.BusinessDate, runOptions).ConfigureAwait(false);
122. 
123.             if (options.JsonOutput)
124.             {
125.                 System.Console.Out.Write(reportBuilder.BuildJson(result));
126.                 System.Console.Out.Write('\n');
127.             }
128.             else
129.             {
130.                 System.Console.WriteLine();
131.                 System.Console.WriteLine($"Business date : {result.BusinessDate:yyyy-MM-dd}");
132.                 System.Console.WriteLine($"Matched pairs : {result.Matches.Count}");
133.                 System.Console.WriteLine($"Open breaks   : {result.OpenBreaks.Count}");
134.                 System.Console.WriteLine($"Overridden    : {result.OverriddenBreaks.Count}");
135.                 System.Console.WriteLine($"Status        : {EndOfDayReportBuilder.StatusText(result)}");
136.                 System.Console.WriteLine($"Reports       : {options.OutputDirectory}");
137.             }
138. 
139.             return result.IsClean ? ExitClean : ExitBreaks;
140.         }
141.         catch (Exception ex) when (ex is FileNotFoundException or DirectoryNotFoundException or FormatException)
